def soe(n):
    primes = [True] * (n + 1)
    primes[0] = primes[1] = False
    i = 4
    while i < n:
        primes[i] = False
        i += 2
    i = 3
    while i * i <= n:
        for j in range(i * i, n, 2 * i):
            primes[j] = False
        i += 2
    ans = []
    for i in range(len(primes)):
        if primes[i]:
            ans.append(i)
    return ans


