ans = 1 + comp_ones_frees(sum(bink), 0)
ones = 0
for i in range(len(bink)):
    if bink[i] == 0:
        continue
    ans += comp_ones_frees(ones, len(bink) - i - 1)
    ones += 1
print(ans % MOD)

