    n = len(s)
    if n == 1:
        if s in "0_X":
            print(1)
        else:
            print(0)
        return

    def canmatchlen2(s1, s2):
        for i in range(2):
            if s1[i] == "_" or s1[i] == s2[i]:
                continue
            else:
                return False
        return True

    def count(s):
        if s == "0" * n:
            return 1
        if n > 1 and s[0] == "0":
            return 0
        last2 = s[n - 2 :]
        last2cnts = 0
        for s2 in ["00", "25", "50", "75"]:
            if canmatchlen2(last2, s2):
                last2cnts += 1
        if n == 2:
            if canmatchlen2(last2, "00"):
                last2cnts -= 1
            return last2cnts
        otherscnts = 1
        for i in range(n - 2):
            if s[i] == "_":
                if i == 0:
                    otherscnts *= 9
                else:
                    otherscnts *= 10
        return last2cnts * otherscnts

    ans = 0
    if "X" in s:
        for x in [str(z) for z in range(10)]:
            ans += count(s.replace("X", x))
    else:
        ans = count(s)
    print(ans)
    return


