        x += 1
    k = x * d - a
    lcm = ((a + k) * (b + k)) // gcd(a + k, b + k)
    if lcm < ans:
        print(k)
    elif lcm > ans:
        print(d1[ans])
    else:
        print(min(k, d1[ans]))

