primes = []


def list_primes_upto(upto: int):
    pcl = [1 for x in range(upto + 1)]
    global primes
    primes = []
    if upto >= 2:
        primes.append(2)
    if upto >= 3:
        primes.append(3)
    for i in range(6, upto + 2, 6):
        if i - 1 <= upto and pcl[i - 1] == 1:
            primes.append(i - 1)
            for k in range((i - 1) ** 2, upto + 1, (i - 1) * 2):
                pcl[k] = 0
        if i + 1 <= upto and pcl[i + 1] == 1:
            primes.append(i + 1)
            for k in range((i + 1) ** 2, upto + 1, (i + 1) * 2):
                pcl[k] = 0
    return


